<template>
  <component :is="embedded ? 'section' : ElDialog" :model-value="modelValue" title="权益包应用范围" width="min(900px,96vw)" top="5vh" :close-on-click-modal="false" :before-close="close" :show-close="!busy" data-sales-binding-dialog destroy-on-close>
    <details v-if="recoverableCopies.length && !planEditorOpen" class="context-details" data-binding-other-workcopies><summary>其他范围或旧格式工作草稿（{{recoverableCopies.length}}）</summary><article v-for="entry in recoverableCopies" :key="entry.copy.key"><span>{{copyRangeLabel(entry.copy.draft)}} · {{entry.legacy?'旧格式，待核对':'已保存工作草稿'}}</span><el-button link type="primary" :disabled="busy" @click="restoreCopy(entry.copy)">恢复此范围草稿</el-button></article></details>
    <p v-if="draft?.scope.kind==='model'" class="muted" data-binding-actual-scope>实际编辑范围：{{copyRangeLabel(draft)}}</p>
    <el-form v-if="draft && !planEditorOpen" label-position="top" :disabled="busy || !canEdit">
      <details v-if="contextual" class="context-details"><summary>范围与来源详情</summary><p>{{draft.name}} · {{draft.source}}</p><p>{{draft.scope.kind==='model'?`${draft.scope.modelId} · ${draft.scope.versionId||'模型草稿'}`:draft.id}}</p></details>
      <template v-if="!contextual">
      <div class="form-grid"><el-form-item label="绑定名称"><el-input v-model="draft.name" aria-label="绑定名称" placeholder="例如：手机机型选配"/></el-form-item><el-form-item label="作用来源"><el-select :model-value="draft.scope.kind" aria-label="绑定来源类型" @change="changeSource"><el-option value="model" label="模型 / 规格范围"/><el-option value="products" label="明确的真实商品范围"/></el-select></el-form-item></div>
      <template v-if="draft.scope.kind==='model'">
        <div class="form-grid"><el-form-item label="商品模型"><el-select :model-value="draft.scope.modelId" filterable aria-label="绑定模型" @change="changeModel"><el-option v-for="model in models" :key="model.id" :value="model.id" :label="model.name"/></el-select></el-form-item><el-form-item label="来源版本"><el-select :model-value="draft.scope.versionId||'$draft'" aria-label="来源模型版本" @change="changeVersion"><el-option value="$draft" label="当前模型草稿 · 仅预览"/><el-option v-for="version in versions" :key="version.id" :value="version.id" :label="`${version.versionName || 'v'+version.version} · ${version.status==='published'?'已发布':'已下线'}`" :disabled="version.status!=='published'"/></el-select></el-form-item></div>
      </template>
      <div v-else class="form-grid"><el-form-item label="商品范围"><el-select v-model="draft.scope.familyIds" multiple filterable collapse-tags aria-label="绑定商品范围"><el-option v-for="family in store.data.families" :key="family.id" :value="family.id" :label="`${family.name} · ${family.oaProductId||family.id}`"/></el-select></el-form-item><el-form-item label="或指定 SKU"><el-select v-model="draft.scope.skuIds" multiple filterable collapse-tags aria-label="绑定 SKU 范围"><el-option v-for="sku in skus" :key="sku.id" :value="sku.id" :label="sku.label"/></el-select></el-form-item></div>
      </template>
      <el-form-item label="匹配方式"><el-radio-group :model-value="draft.mode" aria-label="方案匹配方式" @change="changeMode"><el-radio-button v-if="draft.scope.kind==='model'" value="default">模板默认</el-radio-button><el-radio-button value="replace">此范围单独设置</el-radio-button><el-radio-button value="none">此范围不展示选配</el-radio-button></el-radio-group></el-form-item>
      <SalesScopePicker ref="scopePicker" v-if="draft.scope.kind==='model' && draft.mode!=='default'" :key="`${draft.scope.modelId}:${draft.scope.versionId||'draft'}:${draft.id}`" v-model="draft.scope.selector" :model-id="draft.scope.modelId" :version-id="draft.scope.versionId" :initial-node-id="draft.scope.nodeId" :initialize-node-selection="false" @validity-change="scopeValid=$event" @pending-change="scopePending=$event"/>
      <div v-if="draft.mode!=='none'" class="form-grid"><el-form-item label="选配方案"><div class="inline-control"><el-select :model-value="draft.planId||''" filterable aria-label="选择选配方案" @change="changePlan"><el-option v-for="plan in (store.data.salesOptionPlans||[]).filter(item=>item.schemaVersion===1)" :key="plan.id" :value="plan.id" :label="`${plan.name}${plan.status==='disabled'?'（停用）':!plan.publishedVersion?'（待发布）':''}`"/></el-select><el-button v-if="draft.planId" link @click="editPlan(false)">编辑共享方案</el-button><el-button v-if="draft.planId && store.can('product:sales-config:create')" link @click="editPlan(true)">复制后调整</el-button><el-button v-if="store.can('product:sales-config:create')" link @click="planEditorId='';planCopyId='';planEditorOpen=true">新建</el-button></div></el-form-item><el-form-item label="方案版本"><el-select v-model="draft.planVersion" aria-label="选配方案版本" placeholder="选择已发布版本"><el-option v-for="version in selectedPlan?.versions||[]" :key="version.version" :value="version.version" :label="`v${version.version} · ${version.name}`"/></el-select></el-form-item></div>
      <ul v-if="selectedPlanSnapshot" class="plan-summary"><li v-for="item in selectedPlanSnapshot.items.filter(item=>item.enabled)" :key="item.id">{{item.name}}：{{item.required?'必选':'可选'}}，最多 {{item.maxKinds}} 款<span v-if="item.service"> · {{item.service.description}} · {{item.service.unit}}<template v-if="item.service.validity"> · {{item.service.validity}}</template></span></li></ul><p v-if="selectedPlan" class="muted">共享方案 · {{planUsage}} 个正式范围使用；修改草稿后仍需发布并核对绑定版本。</p>
      <el-form-item v-if="!contextual" label="配置来源"><el-input v-model="draft.source" aria-label="绑定配置来源" placeholder="例如：门店销售选配规则"/></el-form-item>
    </el-form>
    <section v-if="preview && !planEditorOpen" class="coverage" data-sales-binding-preview>
      <div class="counts"><span><strong data-sales-legal-count>{{preview.legalCount}}</strong> 合法规格</span><span><strong data-sales-sku-count>{{preview.skuCount}}</strong> 当前销售 SKU</span><el-tag v-if="preview.draftOnly" type="info">草稿预览</el-tag></div>
      <details v-if="preview.samples.length"><summary>查看覆盖样本（{{preview.samples.length}}）</summary><ul><li v-for="sample in preview.samples.slice(0,20)" :key="sample.identityKey">{{sample.label}}<span class="muted"> · 当前 SKU {{sample.skuIds.length}} 条</span></li></ul></details>
      <el-alert v-for="issue in preview.issues" :key="issue" :title="issue" type="warning" :closable="false"/>
      <details v-if="preview.unresolved.length" open><summary>未能准确解析 {{preview.unresolved.length}} 项</summary><ul><li v-for="item in preview.unresolved.slice(0,20)" :key="item.id">{{item.id}}：{{item.message}}</li></ul></details>
      <p v-if="preview.draftOnly" class="muted">应用到现有商品前，请选择其实际来源的已发布模型版本。草稿不会作为正式适用依据。</p>
    </section>
    <el-alert v-if="error" :title="error" type="error" :closable="false" role="alert"/>
    <el-alert v-if="copyConflict" title="正式配置已被其他操作更新，工作草稿已保留。重新核对当前版本后再保存或应用。" type="warning" :closable="false"><el-button link @click="reviewLatest">重新核对当前版本</el-button></el-alert>
    <div v-if="!planEditorOpen" class="binding-actions"><span v-if="dirty" class="muted">有未保存修改</span><span v-else-if="workingRevision" class="muted" data-binding-working-saved>工作草稿已保存 · 正式配置保持原样</span><el-button :disabled="busy" @click="close()">{{embedded?'返回当前结果':'关闭'}}</el-button><el-button v-if="canEdit" :loading="busy" :disabled="!scopeReady || copyConflict" data-sales-save-binding-draft @click="save(false)">保存工作草稿</el-button><el-button v-if="canPublish" type="primary" :loading="busy" :disabled="!preview?.canApply || !scopeReady || copyConflict" data-sales-apply-binding @click="save(true)">{{draft?.enabled?'更新正式配置':draft?.scope.kind==='products'?'应用到商品范围':'应用到已发布范围'}}</el-button></div>
    <SalesPlanEditor ref="planEditor" v-model="planEditorOpen" :plan-id="planEditorId" :copy-id="planCopyId" :embedded="embedded" keep-open-after-save @saved="id=>{changePlan(id)}"/>

  </component>
</template>
<script setup lang="ts">
import {computed,onBeforeUnmount,ref,watch} from 'vue'
import {ElDialog,ElMessageBox} from 'element-plus'
import {onBeforeRouteLeave} from 'vue-router'
import {useCatalogStore,uid} from '../../stores/catalog'
import {isRealSku} from '../../domain/catalogIdentity'
import {savedSkuName,savedSkuCode} from '../../domain/productList'
import {previewSalesBinding,salesBindingContext,salesSignature} from '../../domain/salesConfiguration'
import {salesBindingWorkingIdentity,salesBindingWorkingTaskKey,salesBindingWorkingIdentityEquals,type SalesBindingWorkingIdentity,type SalesBindingWorkingCopy} from '../../domain/salesBindingWorkingCopy'
import {templateSelectorCoverage} from '../../domain/templateCompatibility'
import type {SalesOptionBinding} from '../../domain/salesConfigurationTypes'
import SalesScopePicker from './SalesScopePicker.vue'
import SalesPlanEditor from './SalesPlanEditor.vue'
const props=defineProps<{modelValue:boolean;bindingId?:string;modelId?:string;nodeId?:string;versionId?:string|null;readonly?:boolean;embedded?:boolean;contextual?:boolean;initialDraft?:SalesOptionBinding;taskIdentity?:SalesBindingWorkingIdentity;recoveryKey?:string;recoveryRevision?:number}>()
const emit=defineEmits<{'update:modelValue':[boolean];saved:[string];'context-change':[SalesOptionBinding,string]}>()
const store=useCatalogStore(),draft=ref<SalesOptionBinding>(),baseline=ref(''),busy=ref(false),error=ref(''),planEditorOpen=ref(false),planEditorId=ref(''),planCopyId=ref(''),workingRevision=ref(0),copyConflict=ref(false),baseRevision=ref(0)
const planEditor=ref<InstanceType<typeof SalesPlanEditor>>()
let requestId='',epoch=0,alive=true
const clone=<T,>(value:T):T=>JSON.parse(JSON.stringify(value))
const entryNodeId=ref(''),loadedKey=ref(''),copyEpoch=ref(0),recoveryProof=ref<{key:string;revision:number;stamp:string}>()
const scopeValid=ref(true),scopePending=ref(false),scopePicker=ref<InstanceType<typeof SalesScopePicker>>()
const scopeReady=computed(()=>draft.value?.scope.kind!=='model'||draft.value.mode==='default'||!!draft.value.scope.selector&&scopeValid.value&&!scopePending.value)
const workingIdentity=computed(()=>draft.value?salesBindingWorkingIdentity(draft.value,entryNodeId.value):undefined)
const workingKey=computed(()=>draft.value?salesBindingWorkingTaskKey(draft.value,entryNodeId.value):'')
const recoverableCopies=computed(()=>{copyEpoch.value;if(!store.can('product:sales-config:read')||!draft.value)return [];const result=store.listSalesBindingWorkingCopies();return result.copies.filter(entry=>(entry.copy.key!==loadedKey.value||workingRevision.value===0)&&(draft.value!.id?entry.copy.draft.id===draft.value!.id:!entry.copy.draft.id&&entry.copy.draft.scope.kind==='model'&&draft.value!.scope.kind==='model'&&entry.copy.draft.scope.modelId===draft.value!.scope.modelId))})
const dirty=computed(()=>scopePending.value||!!draft.value&&JSON.stringify(draft.value)!==baseline.value)
const canEdit=computed(()=>!props.readonly&&store.can('product:sales-config:update'))
const canPublish=computed(()=>canEdit.value&&store.can('product:sales-config:publish'))
const models=computed(()=>store.data.specCanvases.map(item=>({id:item.templateId,name:item.name||store.data.templates.find(x=>x.id===item.templateId)?.name||item.templateId})))
const versions=computed(()=>draft.value?.scope.kind==='model'?store.data.specModelVersions.filter(item=>item.templateId===(draft.value!.scope as Extract<SalesOptionBinding['scope'],{kind:'model'}>).modelId).sort((a,b)=>b.version-a.version):[])
const skus=computed(()=>store.data.skus.filter(item=>isRealSku(store.data,item)).map(item=>({id:item.id,label:`${savedSkuName(item)} · ${savedSkuCode(item)}`})))
const selectedPlan=computed(()=>store.data.salesOptionPlans?.find(item=>item.schemaVersion===1&&item.id===draft.value?.planId))
const selectedPlanSnapshot=computed(()=>selectedPlan.value?.versions.find(version=>version.version===draft.value?.planVersion))
const planUsage=computed(()=>(store.data.salesOptionBindings||[]).filter(binding=>binding.schemaVersion===1&&binding.enabled&&binding.planId===draft.value?.planId).length)
const preview=computed(()=>draft.value?previewSalesBinding(store.data,draft.value):undefined)
function copyRangeLabel(value:SalesOptionBinding){if(value.scope.kind!=='model')return `明确商品：${value.scope.familyIds.join('、')} / ${value.scope.skuIds.join('、')}`;const c=salesBindingContext(store.data,value.scope.modelId,value.scope.versionId),coverage=value.mode==='default'?new Set(c.combinations.map(item=>item.identityKey)):value.scope.selector?templateSelectorCoverage(c,value.scope.selector).identities:new Set<string>();const labels=c.combinations.filter(item=>coverage.has(item.identityKey)).map(item=>item.label);return `${value.scope.versionId||'模型草稿'} · ${value.mode==='default'?'模板默认':value.mode==='none'?'不展示选配':'单独设置'} · ${labels.slice(0,3).join('；')||'范围待核对'}${labels.length>3?` 等 ${labels.length} 条规格`:''}`}
let loading=false
function installDraft(value:SalesOptionBinding,identity:SalesBindingWorkingIdentity,work?:SalesBindingWorkingCopy,conflict=false){loading=true;draft.value=clone(value);entryNodeId.value=identity.entryNodeId||'';loadedKey.value=salesBindingWorkingTaskKey(draft.value,entryNodeId.value);workingRevision.value=work?.key===loadedKey.value?work.revision:0;baseRevision.value=work?.baseRevision??value.revision;copyConflict.value=conflict;scopePending.value=false;scopeValid.value=true;baseline.value=JSON.stringify(draft.value);loading=false;emit('context-change',clone(draft.value),entryNodeId.value)}
watch(()=>[props.modelValue,props.bindingId,props.modelId,props.nodeId,props.versionId,props.recoveryKey,store.activeUserId,store.previewUserId],()=>{if(!props.modelValue)return;epoch++;planEditorOpen.value=false;requestId=uid('sales-binding-request');error.value='';recoveryProof.value=undefined;copyEpoch.value++;const found=store.data.salesOptionBindings?.find(item=>item.id===props.bindingId);const seed:SalesOptionBinding=props.initialDraft?clone(props.initialDraft):found?clone(found):{schemaVersion:1,id:'',revision:0,name:props.nodeId?'节点选配':props.modelId?'模型默认选配':'',enabled:false,scope:{kind:'model',modelId:props.modelId||'',versionId:props.versionId||null,...(props.nodeId?{nodeId:props.nodeId}:{})},mode:props.nodeId?'replace':'default',planId:null,planVersion:null,source:'人工配置',updatedAt:''};const identity=props.taskIdentity||salesBindingWorkingIdentity(seed,props.nodeId);const key=salesBindingWorkingTaskKey(seed,identity.entryNodeId);const work=store.getSalesBindingWorkingCopy(props.recoveryKey||key,props.recoveryKey?undefined:identity);if(props.recoveryKey&&(!work.copy||work.copy.revision!==props.recoveryRevision)){installDraft(seed,identity);error.value='待恢复草稿已变化，请返回重新核对范围。';copyConflict.value=true;return}if(work.copy){const restoredIdentity=props.recoveryKey?salesBindingWorkingIdentity(work.copy.draft,work.copy.identity?.entryNodeId||work.copy.draft.scope.kind==='model'&&work.copy.draft.scope.nodeId||''):identity;installDraft(work.copy.draft,restoredIdentity,work.copy,!!work.conflict);if(props.recoveryKey)recoveryProof.value={key:work.copy.key,revision:work.copy.revision,stamp:salesSignature(work.copy)}}else installDraft(seed,identity);if(!work.ok)error.value=work.message||'工作草稿暂时无法读取，原内容保留。'},{immediate:true})
watch(()=>workingIdentity.value,identity=>{if(loading||!draft.value||!identity)return;const key=workingKey.value;if(key!==loadedKey.value){const other=store.getSalesBindingWorkingCopy(key,identity);loadedKey.value=key;workingRevision.value=0;copyConflict.value=!!other.copy;recoveryProof.value=undefined;if(other.copy)error.value='这个范围已有工作草稿，先从下方入口明确恢复并核对，当前输入未覆盖它。'}emit('context-change',clone(draft.value),entryNodeId.value)},{flush:'sync'})
async function restoreCopy(copy:SalesBindingWorkingCopy){if(!await canDiscard())return;const current=store.getSalesBindingWorkingCopy(copy.key);if(!current.copy||current.copy.revision!==copy.revision){error.value='工作草稿已变化，请重新打开核对。';copyEpoch.value++;return}epoch++;scopePicker.value?.discardPending();const identity=salesBindingWorkingIdentity(current.copy.draft,current.copy.identity?.entryNodeId||(current.copy.draft.scope.kind==='model'?current.copy.draft.scope.nodeId:undefined));installDraft(current.copy.draft,identity,current.copy,!!current.conflict);recoveryProof.value={key:copy.key,revision:copy.revision,stamp:salesSignature(current.copy)};requestId=uid('sales-binding-request');error.value=current.legacy?'已恢复旧工作草稿，请核对上方实际范围。保存将建立新版身份，旧 key 内容保留。':'';copyEpoch.value++}

function editPlan(copy:boolean){planEditorId.value=copy?'':draft.value?.planId||'';planCopyId.value=copy?draft.value?.planId||'':'';planEditorOpen.value=true}
async function reviewLatest(){try{await ElMessageBox.confirm('保留当前工作草稿，以最新正式修订重新计算范围和冲突。请再次检查方案与版本后应用。','重新核对正式配置',{confirmButtonText:'保留草稿并重新核对',cancelButtonText:'返回'})}catch{return}const latest=store.data.salesOptionBindings?.find(item=>item.id===draft.value?.id);baseRevision.value=latest?.revision||0;if(draft.value)draft.value.revision=baseRevision.value;copyConflict.value=false;error.value='';requestId=uid('sales-binding-request')}

async function changeSource(kind:string){if(!draft.value||!await canChangeScope())return;entryNodeId.value='';draft.value.scope=kind==='model'?{kind:'model',modelId:props.modelId||'',versionId:null}:{kind:'products',familyIds:[],skuIds:[]};draft.value.mode=kind==='model'?'default':'replace'}
async function changeModel(id:string){if(draft.value?.scope.kind!=='model'||!await canChangeScope())return;entryNodeId.value='';draft.value.scope={kind:'model',modelId:id,versionId:null};draft.value.mode='default'}
async function changeVersion(id:string){if(draft.value?.scope.kind!=='model'||!await canChangeScope())return;draft.value.scope={...draft.value.scope,versionId:id==='$draft'?null:id,selector:undefined}}
async function changeMode(mode:SalesOptionBinding['mode']){if(!draft.value||!await canChangeScope())return;draft.value.mode=mode;if(draft.value.mode==='default'&&draft.value.scope.kind==='model'){delete draft.value.scope.selector;delete draft.value.scope.nodeId}if(draft.value.mode==='none'){draft.value.planId=null;draft.value.planVersion=null}}
function changePlan(id:string){if(!draft.value)return;draft.value.planId=id||null;draft.value.planVersion=store.data.salesOptionPlans?.find(item=>item.id===id)?.publishedVersion??null}
async function canChangeScope(){if(!scopePending.value)return true;try{await ElMessageBox.confirm('规格范围还有未应用的输入，放弃后切换？','未应用范围输入',{confirmButtonText:'放弃输入并切换',cancelButtonText:'继续编辑'})}catch{return false}scopePicker.value?.discardPending();return true}
async function canDiscard(){if(busy.value)return false;if(planEditorOpen.value&&planEditor.value&&!await planEditor.value.canDiscard())return false;if(dirty.value){try{await ElMessageBox.confirm('选配绑定尚未保存，放弃本次输入？','未保存修改',{confirmButtonText:'放弃修改',cancelButtonText:'继续编辑'})}catch{return false}}return true}
async function close(done?:()=>void){if(!await canDiscard())return;emit('update:modelValue',false);done?.()}
async function save(enabled:boolean){
  if(!draft.value||busy.value||!scopeReady.value||!canEdit.value||copyConflict.value||enabled&&!canPublish.value)return
  const candidate={...clone(draft.value),...(enabled?{enabled:true}:{})},reviewed=previewSalesBinding(store.data,candidate)
  const input=JSON.stringify(draft.value),scopeInput=scopePicker.value?.inputSignature,version=epoch,owner=store.activeUserId,identity=store.previewUserId,key=workingKey.value,task=workingIdentity.value!
  const current=()=>alive&&version===epoch&&props.modelValue&&owner===store.activeUserId&&identity===store.previewUserId&&input===JSON.stringify(draft.value)&&scopeInput===scopePicker.value?.inputSignature&&scopeReady.value&&salesBindingWorkingIdentityEquals(task,workingIdentity.value!)&&(!recoveryProof.value||salesSignature(store.getSalesBindingWorkingCopy(recoveryProof.value.key).copy)===recoveryProof.value.stamp)
  if(enabled){if(!reviewed.canApply)return;try{await ElMessageBox.confirm(`将此销售绑定应用到 ${reviewed.legalCount} 条合法规格、当前 ${reviewed.skuCount} 条销售 SKU？商品规格、已发布模型和历史清单保持原样。`,'确认应用范围',{confirmButtonText:'启用此绑定',cancelButtonText:'继续核对'})}catch{return}}
  if(!current()){error.value='输入或操作者已变化，请重新核对范围。';return}
  busy.value=true;error.value=''
  try{
    if(!enabled){const result=await store.saveSalesBindingWorkingCopy({key,identity:task,draft:candidate,baseRevision:baseRevision.value,expectedRevision:workingRevision.value},current);if(!result.ok){error.value=result.message||'保存失败，输入已保留。';copyConflict.value='conflict' in result&&!!result.conflict;return}workingRevision.value=result.copy?.revision||workingRevision.value;recoveryProof.value=undefined;copyEpoch.value++;baseline.value=JSON.stringify(draft.value);return}
    const stored=store.getSalesBindingWorkingCopy(key,task)
    if(workingRevision.value&&(!stored.copy||!salesBindingWorkingIdentityEquals(stored.copy.identity!,task))){const flushed=await store.saveSalesBindingWorkingCopy({key,identity:task,draft:candidate,baseRevision:baseRevision.value,expectedRevision:workingRevision.value},current);if(!flushed.ok){error.value=flushed.message||'当前工作范围未保存，正式配置保持原样。';return}workingRevision.value=flushed.copy!.revision;recoveryProof.value=undefined}
    const result=await store.saveSalesOptionBinding({draft:candidate,expectedRevision:baseRevision.value,expectedBasis:reviewed.stamp,requestId,workingContext:{key,identity:task,expectedRevision:workingRevision.value}},current);if(!result.ok){error.value=result.message||'保存失败，输入已保留。';return}
    if(workingRevision.value)await store.discardSalesBindingWorkingCopy(key,workingRevision.value,current)
    baseline.value=JSON.stringify(draft.value);emit('saved',result.id!);emit('update:modelValue',false)
  }catch(cause){error.value=cause instanceof Error?cause.message:'保存失败，输入已保留。'}finally{busy.value=false}
}
function acceptContextChange(){scopePicker.value?.discardPending();scopePending.value=false;baseline.value=JSON.stringify(draft.value);planEditor.value?.acceptContextChange()}
defineExpose({canDiscard,acceptContextChange,dirty,busy})

onBeforeRouteLeave(async()=>{if(props.embedded||!props.modelValue)return true;await close();return !props.modelValue})
function refreshCopies(event:StorageEvent){if(event.key?.startsWith('iyge-sales-binding-work:'))copyEpoch.value++}
window.addEventListener('storage',refreshCopies)
onBeforeUnmount(()=>{alive=false;epoch++;window.removeEventListener('storage',refreshCopies)})
</script>
